-- ---- 테이블: label_background_categories ----
DROP TABLE IF EXISTS "label_background_categories" CASCADE;
CREATE TABLE "label_background_categories" (
  "id" SERIAL NOT NULL,
  "background_id" TEXT NOT NULL,
  "category_id" INTEGER NOT NULL,
  "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

-- ---- 테이블: label_categories ----
DROP TABLE IF EXISTS "label_categories" CASCADE;
CREATE TABLE "label_categories" (
  "id" SERIAL NOT NULL,
  "name" TEXT NOT NULL,
  "slug" TEXT NOT NULL,
  "description" TEXT,
  "is_active" BOOLEAN DEFAULT true,
  "display_order" INTEGER DEFAULT 0,
  "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

-- ---- 테이블: label_comments ----
DROP TABLE IF EXISTS "label_comments" CASCADE;
CREATE TABLE "label_comments" (
  "id" SERIAL NOT NULL,
  "order_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "content" TEXT NOT NULL,
  "created_at" TIMESTAMP DEFAULT now(),
  "updated_at" TIMESTAMP DEFAULT now(),
  PRIMARY KEY ("id")
);

-- ---- 테이블: label_likes ----
DROP TABLE IF EXISTS "label_likes" CASCADE;
CREATE TABLE "label_likes" (
  "id" SERIAL NOT NULL,
  "order_id" TEXT NOT NULL,
  "user_id" INTEGER NOT NULL,
  "created_at" TIMESTAMP DEFAULT now(),
  PRIMARY KEY ("id")
);

-- ---- 테이블: label_ratings ----
DROP TABLE IF EXISTS "label_ratings" CASCADE;
CREATE TABLE "label_ratings" (
  "id" SERIAL NOT NULL,
  "order_id" TEXT NOT NULL,
  "user_id" TEXT NOT NULL,
  "rating" NUMERIC NOT NULL,
  "created_at" TIMESTAMP DEFAULT now(),
  "updated_at" TIMESTAMP DEFAULT now(),
  PRIMARY KEY ("id")
);

-- ---- 테이블: notifications ----
DROP TABLE IF EXISTS "notifications" CASCADE;
CREATE TABLE "notifications" (
  "id" TEXT DEFAULT gen_random_uuid() NOT NULL,
  "customer_email" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "title" TEXT NOT NULL,
  "message" TEXT NOT NULL,
  "order_id" TEXT,
  "is_read" BOOLEAN DEFAULT false,
  "created_at" TIMESTAMP DEFAULT now(),
  PRIMARY KEY ("id")
);

-- ---- 테이블: orders ----
DROP TABLE IF EXISTS "orders" CASCADE;
CREATE TABLE "orders" (
  "id" TEXT NOT NULL,
  "customer_name" TEXT NOT NULL,
  "customer_email" TEXT NOT NULL,
  "customer_phone" TEXT,
  "customer_address" TEXT,
  "customer_zip_code" TEXT,
  "bottle_id" TEXT NOT NULL,
  "bottle_name" TEXT NOT NULL,
  "quantity" INTEGER DEFAULT 1 NOT NULL,
  "amount" INTEGER NOT NULL,
  "status" TEXT DEFAULT 'pending'::text,
  "payment_id" TEXT,
  "label_design" JSONB NOT NULL,
  "label_image" TEXT,
  "delivery_method" TEXT DEFAULT 'standard'::text,
  "delivery_fee" INTEGER DEFAULT 3000,
  "user_id" INTEGER,
  "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  "publish_to_gallery" BOOLEAN DEFAULT false,
  "title" TEXT,
  "shipping_notified_at" TIMESTAMP,
  "tracking_number" TEXT,
  "shipping_company" TEXT,
  "shipping_notified" BOOLEAN DEFAULT false,
  PRIMARY KEY ("id")
);

-- ---- 테이블: users ----
DROP TABLE IF EXISTS "users" CASCADE;
CREATE TABLE "users" (
  "id" SERIAL NOT NULL,
  "username" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "password" TEXT NOT NULL,
  "display_name" TEXT,
  "photo_url" TEXT,
  "phone" TEXT,
  "user_type" TEXT DEFAULT 'user'::text,
  "is_approved" BOOLEAN DEFAULT false,
  "is_super_user" BOOLEAN DEFAULT false,
  "franchise_info" JSONB,
  "stripe_customer_id" TEXT,
  "stripe_subscription_id" TEXT,
  "partner_id" TEXT,
  "partner_status" TEXT DEFAULT 'pending'::text,
  "bank_info" JSONB,
  "created_at" TIMESTAMP DEFAULT now(),
  PRIMARY KEY ("id")
);

-- ---- 테이블: wine_bottles ----
DROP TABLE IF EXISTS "wine_bottles" CASCADE;
CREATE TABLE "wine_bottles" (
  "id" VARCHAR(50) NOT NULL,
  "name" VARCHAR(100) NOT NULL,
  "image" VARCHAR(255) NOT NULL,
  "type" VARCHAR(10) NOT NULL,
  "bottle_type" VARCHAR(20) NOT NULL,
  "dimensions" VARCHAR(100),
  "capacity" VARCHAR(20),
  "price" INTEGER NOT NULL,
  "label_width" NUMERIC NOT NULL,
  "label_height" NUMERIC NOT NULL,
  "label_position_top" INTEGER NOT NULL,
  "label_position_left" INTEGER NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

-- ---- 외래키 제약조건 ----
ALTER TABLE "orders" ADD CONSTRAINT "orders_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "label_background_categories" ADD CONSTRAINT "label_background_categories_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "label_categories" ("id");
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_order_id_fkey" FOREIGN KEY ("order_id") REFERENCES "orders" ("id");

